-- Buscar cuba de iogurte existente
SELECT id, nome, setor, ativo FROM produtos_master 
WHERE unaccent(lower(nome)) ILIKE unaccent(lower('%iogurte%'));

UPDATE estoque SET quantidade_atual = 0, updated_at = now()
WHERE loja_id = 1 AND produto_master_id IN (922, 1187, 1191, 1195);

UPDATE estoque_lotes SET quantidade = 0, updated_at = now()
WHERE loja_id = 1 AND produto_id IN (922, 1187, 1191, 1195);

SELECT pm.id, pm.nome, COALESCE(e.quantidade_atual, 0) AS saldo
FROM produtos_master pm
LEFT JOIN estoque e ON e.produto_master_id = pm.id AND e.loja_id = 1
WHERE pm.id IN (922, 1187, 1191, 1195);

-- Restaurar estoque
UPDATE estoque SET quantidade_atual = 120, updated_at = now()
WHERE loja_id = 1 AND produto_master_id = 922;

UPDATE estoque SET quantidade_atual = 37, updated_at = now()
WHERE loja_id = 1 AND produto_master_id = 1187;

-- Ver quantos lotes existem por produto para restaurar proporcionalmente
SELECT produto_id, COUNT(*) as num_lotes
FROM estoque_lotes
WHERE loja_id = 1 AND produto_id IN (922, 1187)
GROUP BY produto_id;

-- Encontrar brownie lowcarb
SELECT id, nome, setor FROM produtos_master
WHERE ativo = true AND unaccent(lower(nome)) LIKE unaccent(lower('%brownie%low%'));

