const processBatch = async (type: "entrada" | "saida") => {
    if (scannedItems.length === 0 || !selectedStore) {
        toast({ title: "Atenção", description: "Lista vazia ou loja não selecionada.", variant: "destructive" });
        return;
    }

    const itemsToProcess = scannedItems.filter(i => i.status === 'pending' || i.status === 'error');
    if (itemsToProcess.length === 0) return;

    setIsProcessing(true);
    let successCount = 0;
    let errorCount = 0;
    let duplicateCount = 0;

    try {
        // Monta o lote inteiro e processa numa única chamada RPC (bipar_lote_scanner).
        // A RPC: re-seleciona estoque por item (saldo acumulado correto na mesma transação),
        // chama bipar_etiqueta por UID (warning se ok=false), insere a movimentação com
        // usuario_id preenchido, e isola falha por item. Qty<=0 volta como error do item.
        // Qty a movimentar = SALDO ATUAL do container (quantidade_disponivel) — container
        // parcial (83/84) sai com 83, não 84. quantidade_interna é só capacidade nominal.
        const p_itens = itemsToProcess.map(item => ({
            id: item.id,
            pid: parseInt(item.data.pid),
            uid: item.data.uid || null,
            lote_id: item.data.lid || null,
            qty: item.etiqueta?.quantidade_disponivel ?? item.data.qty ?? 1,
            tipo_embalagem: item.etiqueta?.tipo_embalagem || null,
            embalagem_nome: item.etiqueta?.embalagem_nome || item.data.emb || null,
            lote: item.data.lote || null,
            payload: item.data,
        }));

        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const { data: rpcRaw, error: rpcErr } = await (supabase.rpc as any)('bipar_lote_scanner', {
            p_loja_id: selectedStore.id,
            p_tipo: type,
            p_itens,
        });

        if (rpcErr) throw new Error(rpcErr.message || 'Falha ao processar o lote');

        const result = rpcRaw as {
            ok: boolean;
            processados?: number;
            falhas?: number;
            resultados?: { id: string; ok: boolean; erro?: string; duplicado?: boolean }[];
        } | null;
        const resultados = result?.resultados ?? [];
        const byId = new Map(resultados.map(r => [r.id, r]));

        // Mensagem clara: duplicado = "já demos entrada" (âmbar, não é falha);
        // erro real = texto amigável (sem SQL cru no card).
        const dupMsg = type === 'entrada' ? 'Já demos entrada nesta caixa' : 'Já demos saída nesta caixa';
        setScannedItems(prev => prev.map(i => {
            const r = byId.get(i.id);
            if (!r) return i;
            if (r.ok) return { ...i, status: 'success' as const, error: undefined };
            if (r.duplicado) return { ...i, status: 'duplicate' as const, error: dupMsg };
            return { ...i, status: 'error' as const, error: formatBipError(r.erro, type) };
        }));

        // Itens que a RPC não retornou (não deveria acontecer) contam como erro.
        for (const item of itemsToProcess) {
            const r = byId.get(item.id);
            if (r?.ok) {
                successCount++;
            } else if (r?.duplicado) {
                duplicateCount++;
            } else {
                errorCount++;
                if (!r) {
                    setScannedItems(prev => prev.map(i => i.id === item.id ? { ...i, status: 'error', error: 'Sem retorno do servidor' } : i));
                }
            }
        }

        if (successCount > 0) {
            playSuccessSound();
            toast({
                title: `Concluído: ${successCount} processados`,
                description: type === 'saida' ? "Saídas registradas com sucesso no estoque." : "Entradas registradas com sucesso no estoque.",
            });

            // Clear successful items after 3 seconds
            setTimeout(() => {
                setScannedItems(prev => prev.filter(i => i.status !== 'success'));
            }, 3000);

