-- Correções pós-QA do fluxo de bipagem:
--
-- FIX 1 — estoque_lotes chaveado por (lote, produto, LOJA).
-- Antes o UPDATE/INSERT de tg_movimentacoes_sync_estoque_lotes ignorava loja_id →
-- bips de lojas diferentes do mesmo lote caíam numa única linha com loja_id NULL,
-- invisível na visão por loja ("só contagem geral, sem lote").
--
-- FIX 2 — bipagem idempotente.
-- bipar_lote_scanner ignorava o resultado de bipar_etiqueta; re-bipar a mesma etiqueta
-- (já 'recebida'/'em_transito') lançava a movimentação de novo → contagem dupla.
-- Agora respeita ok=false (bip duplicado) e devolve o item como 'já contado', sem relançar.

CREATE OR REPLACE FUNCTION public.tg_movimentacoes_sync_estoque_lotes()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.motivo IS DISTINCT FROM 'scanner_lote' THEN
    RETURN NEW;
  END IF;

  IF NEW.lote_id IS NULL OR NEW.produto_master_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Guarda: alteração em estoque_lotes via movimentação não dispara reconciliação fantasma.
  PERFORM set_config('app.skip_lote_reconcile', '1', true);

  IF NEW.tipo_movimentacao = 'entrada' THEN
    UPDATE public.estoque_lotes
       SET quantidade = GREATEST(0, quantidade + NEW.quantidade)
     WHERE lote_id = NEW.lote_id
       AND produto_id = NEW.produto_master_id
       AND loja_id = NEW.loja_id;

  ELSIF NEW.tipo_movimentacao = 'saida' THEN
    UPDATE public.estoque_lotes
       SET quantidade = GREATEST(0, quantidade - NEW.quantidade)
     WHERE lote_id = NEW.lote_id
       AND produto_id = NEW.produto_master_id
       AND loja_id = NEW.loja_id;
  END IF;

  IF NOT FOUND AND NEW.tipo_movimentacao = 'entrada' THEN
    INSERT INTO public.estoque_lotes (lote_id, produto_id, loja_id, quantidade)
    VALUES (NEW.lote_id, NEW.produto_master_id, NEW.loja_id, NEW.quantidade);
  END IF;

  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.bipar_lote_scanner(
    p_loja_id integer,
    p_tipo text,
    p_itens jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    v_usuario_id integer;
    v_item jsonb;
    v_id text;
    v_pid integer;
    v_uid text;
    v_lote_id uuid;
    v_qty numeric;
    v_disp numeric;
    v_interna numeric;
    v_tipo_embalagem text;
    v_embalagem_nome text;
    v_lote text;
    v_payload jsonb;
    v_bip jsonb;
    v_saldo_anterior numeric;
    v_saldo_novo numeric;
    v_motivo text;
    v_observacoes text;
    v_resultados jsonb := '[]'::jsonb;
    v_ok integer := 0;
    v_err integer := 0;
BEGIN
    BEGIN
        v_usuario_id := public.get_usuario_id_from_auth(auth.uid());
    EXCEPTION WHEN OTHERS THEN
        v_usuario_id := NULL;
    END;

    FOR v_item IN SELECT * FROM jsonb_array_elements(p_itens)
    LOOP
        v_id := v_item->>'id';
        BEGIN
            v_pid := (v_item->>'pid')::integer;
            v_uid := NULLIF(v_item->>'uid', '');
            v_lote_id := NULLIF(v_item->>'lote_id', '')::uuid;
            v_qty := (v_item->>'qty')::numeric;
            v_tipo_embalagem := NULLIF(v_item->>'tipo_embalagem', '');
            v_embalagem_nome := NULLIF(v_item->>'embalagem_nome', '');
            v_lote := NULLIF(v_item->>'lote', '');
            v_payload := v_item->'payload';

            IF v_uid IS NOT NULL THEN
                BEGIN
                    v_bip := public.bipar_etiqueta(
                        v_uid,
                        CASE WHEN p_tipo = 'entrada' THEN 'entrada' ELSE 'saida' END,
                        jsonb_build_object(
                            'loja_id', p_loja_id,
                            'referencia_tipo', 'scanner_lote',
                            'payload', v_payload
                        )
                    );
                EXCEPTION WHEN OTHERS THEN
                    v_bip := NULL;
                END;

                -- IDEMPOTENCIA: etiqueta ja contada nesta etapa → nao lanca de novo.
                IF v_bip IS NOT NULL AND COALESCE((v_bip->>'ok')::boolean, true) = false THEN
                    v_resultados := v_resultados || jsonb_build_object(
                        'id', v_id, 'ok', false,
                        'erro', COALESCE(NULLIF(v_bip->>'erro',''), 'Etiqueta já contada nesta etapa')
                    );
                    v_err := v_err + 1;
                    CONTINUE;
                END IF;

                -- QTY AUTORITATIVA: o que a caixa realmente tem.
                SELECT quantidade_disponivel, quantidade_interna
                  INTO v_disp, v_interna
                  FROM etiquetas_qr
                 WHERE uid = v_uid;
                v_qty := COALESCE(NULLIF(v_disp, 0), NULLIF(v_interna, 0), v_qty);
            END IF;

            IF v_qty IS NULL OR v_qty <= 0 THEN
                RAISE EXCEPTION '%', CASE WHEN p_tipo='entrada'
                    THEN 'Sem quantidade para dar entrada'
                    ELSE 'Container ja vazio — nada para dar saida' END;
            END IF;

            SELECT COALESCE(quantidade_atual, 0)
              INTO v_saldo_anterior
              FROM estoque
             WHERE produto_master_id = v_pid
               AND loja_id = p_loja_id;

            v_saldo_anterior := COALESCE(v_saldo_anterior, 0);

            IF p_tipo = 'entrada' THEN
                v_saldo_novo := v_saldo_anterior + v_qty;
            ELSE
                v_saldo_novo := GREATEST(0, v_saldo_anterior - v_qty);
            END IF;

            v_motivo := CASE WHEN p_tipo = 'entrada' THEN 'scanner_lote' ELSE 'saida_inteira' END;
            v_observacoes := (CASE WHEN p_tipo = 'entrada' THEN 'Entrada' ELSE 'Saída inteira' END)
                || ' via Scanner QR — ' || COALESCE(v_tipo_embalagem, 'container')
                || ' de ' || v_qty::text || ' ' || COALESCE(v_embalagem_nome, 'un')
                || ' · Lote ' || COALESCE(v_lote, '—');

            INSERT INTO movimentacoes (
                produto_master_id, tipo_movimentacao, quantidade,
                quantidade_anterior, quantidade_nova, motivo, observacoes,
                data_movimentacao, loja_id, lote_id, etiqueta_qr_uid, usuario_id
            ) VALUES (
                v_pid, p_tipo, v_qty,
                v_saldo_anterior, v_saldo_novo, v_motivo, v_observacoes,
                now(), p_loja_id, v_lote_id, v_uid, v_usuario_id
            );

            v_resultados := v_resultados || jsonb_build_object('id', v_id, 'ok', true);
            v_ok := v_ok + 1;

        EXCEPTION WHEN OTHERS THEN
            v_resultados := v_resultados || jsonb_build_object('id', v_id, 'ok', false, 'erro', SQLERRM);
            v_err := v_err + 1;
        END;
    END LOOP;

    RETURN jsonb_build_object(
        'ok', true,
        'processados', v_ok,
        'falhas', v_err,
        'resultados', v_resultados
    );
END;
$$;
